import{z as s,x as o,o as t,c as i,q as l,j as B,D as a,d as A,s as r,S as n}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"对齐评测收束","description":"","frontmatter":{"title":"对齐评测收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/aeval-map.md","filePath":"llm/aeval-map.md","lastUpdated":1791063341000}'),p={name:"llm/aeval-map.md"};function d(D,E,g,m,h,_){const e=o("Mermaid");return t(),i("div",null,[E[2]||(E[2]=l('<h1 id="对齐评测收束" tabindex="-1">对齐评测收束 <a class="header-anchor" href="#对齐评测收束" aria-label="Permalink to &quot;对齐评测收束&quot;">​</a></h1><div class="epigraph"><p>评测的全部产出不是一堆分数，而是一张工作点地图：模型在哪、门禁画在哪、下一个失败大概从哪来。</p><footer>—— 据 Bai et al., 2022、Ganguli et al., 2022、Perez et al., 2022、Sharma et al., 2023 与公开套件口径，按本课程整理</footer></div><p><a href="/llm/aeval-reporting-standard">上一课</a>把数字收成可审计的报告。至此零件齐了：设计原则与红队产线管失败从哪来，过度拒绝、诚实、谄媚三根轴的度量管软失败怎么计数，多轮路径、对齐税、比较协议、对抗门禁管真实负载与公平叙事，报告规范管交付。本课把它们装配成一张地图和一张决策单。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对齐评测的决策散在十处：先建基准还是先红队、三根轴先测哪根、多轮脚本何时上、税怎么归因、跨模型比较怎么站得住、报告给谁看。各自局部最优会互相拆台：没有设计原则的红队产出进不了回归集；没有比较协议的「进步」是尺子换了的假象；没有成对报告的优化滑向单边极端。收束要给的是先后顺序与跨版本不动的部分。</p><p><span class="marginnote">决策单按依赖排序，就像装修先水电后瓦工：顺序反了不是不能干，而是返工——没冻结政策就开测，政策一改全部数字作废；没有对照集就上红队，产出的失败只能看、进不了回归集。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>决策单</strong>，按依赖排序：</p><ol><li><strong>冻结政策与套件</strong>：类别映射表先行，数字还没有，资格先有。</li><li><strong>成对基准立表</strong>：危害集与对照集同表，配合率与越权率互为镜像。</li><li><strong>红队两条产线</strong>：自动化铺广度、人工下深度，漏斗产出私有回归集。</li><li><strong>三轴探针</strong>：越权三分判分、诚实耦合报、谄媚盲判配对基线。</li><li><strong>多轮脚本</strong>：逐轮判分加首违轮分布，接口范围显式声明。</li><li><strong>对齐税配对消融</strong>：权重、提示、门三层分账，分域剖面。</li><li><strong>跨模型钉协议</strong>：冻结 harness、换序、双族、区间、偏差审计表。</li><li><strong>对抗矩阵</strong>：攻击族 × 预算声明，最坏值进门禁，自适应复测。</li><li><strong>报告归档</strong>：五件套加分级披露，负结果入库。</li></ol>',9)),(t(),B(n,null,{default:a(()=>[r(e,{id:"mermaid-69",class:"mermaid",graph:"flowchart%20TD%0A%20%20S1%5B%22%E5%86%BB%E7%BB%93%E6%94%BF%E7%AD%96%E4%B8%8E%E5%A5%97%E4%BB%B6%22%5D%20--%3E%20S2%5B%22%E6%88%90%E5%AF%B9%E5%9F%BA%E5%87%86%E7%AB%8B%E8%A1%A8%22%5D%0A%20%20S2%20--%3E%20S3%5B%22%E7%BA%A2%E9%98%9F%E5%8F%8C%E4%BA%A7%E7%BA%BF%E8%BF%9B%E5%9B%9E%E5%BD%92%E9%9B%86%22%5D%0A%20%20S3%20--%3E%20S4%5B%22%E4%B8%89%E8%BD%B4%E6%8E%A2%E9%92%88%EF%BC%9A%E8%B6%8A%E6%9D%83%20%2F%20%E8%AF%9A%E5%AE%9E%20%2F%20%E8%B0%84%E5%AA%9A%22%5D%0A%20%20S4%20--%3E%20S5%5B%22%E5%A4%9A%E8%BD%AE%E8%84%9A%E6%9C%AC%E4%B8%8E%E9%A6%96%E8%BF%9D%E8%BD%AE%22%5D%0A%20%20S5%20--%3E%20S6%5B%22%E5%AF%B9%E9%BD%90%E7%A8%8E%E4%B8%89%E5%B1%82%E6%B6%88%E8%9E%8D%22%5D%0A%20%20S6%20--%3E%20S7%5B%22%E8%B7%A8%E6%A8%A1%E5%9E%8B%E5%8D%8F%E8%AE%AE%E4%B8%8E%E5%8C%BA%E9%97%B4%22%5D%0A%20%20S7%20--%3E%20S8%5B%22%E5%AF%B9%E6%8A%97%E7%9F%A9%E9%98%B5%E4%B8%8E%E6%9C%80%E5%9D%8F%E5%80%BC%E9%97%A8%E7%A6%81%22%5D%0A%20%20S8%20--%3E%20S9%5B%22%E6%8A%A5%E5%91%8A%E5%BD%92%E6%A1%A3%E4%B8%8E%E5%88%86%E7%BA%A7%E6%8A%AB%E9%9C%B2%22%5D%0A%20%20INV%5B%22%E5%9B%9B%E6%9D%A1%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%20-.-%3E%20S2%0A%20%20INV%20-.-%3E%20S7%0A%20%20INV%20-.-%3E%20S8%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>地图的骨架是四条不变量。<strong>政策先行</strong>：分数是 \\(S(\\theta,P,J)\\)，政策不动，数字没有资格说话。<strong>成对报告</strong>：每个安全数字配一面镜子——配合对越权、准确对弃权、附和对纠正——单边指标的最优点总在极端上，镜子让它出不了门。<strong>版本冻结</strong>：模型、裁判、解码、套件四位一体，比较才是差分；缺任何一位，所谓进步只是换尺。<strong>最坏值思维</strong>：均值给产品看体验，最坏值给门禁看边界，安全声明永远取后者。套件会换代、攻击会演化、政策会收紧——参数全换，这四条不动。</p><p>成对报告为什么能挡住单边刷分，镜子机制画出来是这样：</p>',3)),(t(),B(n,null,{default:a(()=>[r(e,{id:"mermaid-79",class:"mermaid",graph:"flowchart%20LR%0A%20%20M%5B%22%E5%8D%95%E8%BE%B9%E6%8C%87%E6%A0%87%EF%BC%9A%E5%8F%AA%E6%8A%A5%E9%85%8D%E5%90%88%E7%8E%87%22%5D%20--%3E%20G%5B%22%E5%88%B7%E5%88%86%E8%B7%AF%E5%BE%84%EF%BC%9A%E8%A7%81%E9%A2%98%E5%85%A8%E6%8B%92%E5%8D%B3%E6%BB%A1%E5%88%86%22%5D%0A%20%20G%20--%3E%20EXT%5B%22%E6%9C%80%E4%BC%98%E7%82%B9%E6%BB%91%E5%90%91%E6%9E%81%E7%AB%AF%EF%BC%9A%E6%A8%A1%E5%9E%8B%E4%B8%80%E5%BE%8B%E6%8B%92%E7%BB%9D%22%5D%0A%20%20MIR%5B%22%E6%88%90%E5%AF%B9%E6%8A%A5%E5%91%8A%EF%BC%9A%E9%85%8D%E5%90%88%E7%8E%87%20%C3%97%20%E8%B6%8A%E6%9D%83%E7%8E%87%E5%90%8C%E8%A1%A8%22%5D%20--%3E%20LOCK%5B%22%E9%95%9C%E5%AD%90%E4%BA%92%E7%9B%B8%E9%94%81%E4%BD%8F%22%5D%0A%20%20LOCK%20--%3E%20WP%5B%22%E5%8F%AA%E8%83%BD%E5%9C%A8%E4%B8%A4%E8%80%85%E9%97%B4%E9%80%89%E5%B7%A5%E4%BD%9C%E7%82%B9%22%5D%0A%20%20WP%20--%3E%20GATE%5B%22%E6%9E%81%E7%AB%AF%E5%88%86%E6%95%B0%E5%87%BA%E4%B8%8D%E4%BA%86%E9%97%A8%E7%A6%81%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=l('<p><span class="marginnote">\\(S(\\theta,P,J)\\) 读作「分数取决于三件事」：模型 \\(\\theta\\)、政策 \\(P\\)、评测器 \\(J\\)。就像成绩取决于考生、考纲和判卷人三方——只盯着考生苦练，考纲和判卷人一换，分数照样大变，所以政策不动数字没有资格说话。</span></p><p><span class="marginnote">若只做三件事：冻结政策与套件版本；把每个安全数字和它的镜像放进同一张表；给每个对外数字绑五件套与区间。本课程见过的大多数评测翻车，在这三步就被拦住。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这张地图有保鲜期：探针会背题、攻击族会扩容、政策会改版，所以每张表都带版本与日期，过期不续命。地图之外有它不覆盖的两翼：训练侧怎么把工作点移过去——<a href="/llm/refusal-training">拒答训练</a>与<a href="/llm/constitutional-ai">宪法式对齐</a>接棒；线上怎么看着它漂——部署监控接棒。评测交付的始终是同一件事：把「感觉安全」换成「在声明的工作点上，失败率的区间与最坏值可被任何人审计」。数字有资格说话的时候，对齐才谈得上工程。</p><p><span class="marginnote">「探针背题」指评测题混进训练数据后被模型背下来：分数涨了，真实能力没变。所以地图上每张表都带版本和日期——就像试卷定期换题，否则「考得好」只是「背过原题」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策单九步，依赖排序：政策冻结 → 成对基准 → 红队 → 三轴 → 多轮 → 税 → 协议 → 对抗 → 报告。</li><li>四条不变量：政策先行、成对报告、版本冻结、最坏值给门禁；参数换代，顺序不动。</li><li>每个安全数字有镜子；单边披露是作弊策略的重新放行。</li><li>比较需冻结协议，进步曲线要过尺子这一关。</li><li>声明口径止于「工作点上的区间与最坏值」，免疫与绝对安全没有操作定义。</li><li>出处：Bai et al., 2022；Ganguli et al., 2022；Perez et al., 2022；Sharma et al., 2023；Zheng et al., 2023；HarmBench、JailbreakBench、XSTest 官方口径，按本课程整理。</li></ul>',7))])}const C=s(p,[["render",d]]);export{c as __pageData,C as default};
